#include <bits/stdc++.h>
using namespace std;

using Job = pair<pair<int, int>, pair<int, int>>;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int a, b;
    cin >> a >> b;

    vector<vector<Job>> jobs(a + 2);
    vector<int> ans(a + 2, 0);

    for (int i = 0; i < b; ++i) {
        int x, y, z;
        cin >> x >> y >> z;

        if (0 <= y && y < static_cast<int>(ans.size()))
            ans[y] = b + 1;

        if (0 <= x && x < static_cast<int>(jobs.size()))
            jobs[x].push_back({{z, -x}, {y, i + 1}});
    }

    priority_queue<Job, vector<Job>, greater<Job>> q;

    for (int i = 1; i <= a; ++i) {
        for (const Job& job : jobs[i])
            q.push(job);

        if (q.empty())
            continue;

        Job current = q.top();
        int priority = current.first.first;
        int start = current.first.second;
        int deadline = current.second.first;
        int index = current.second.second;

        if (i >= deadline || ans[i] != 0)
            continue;

        q.pop();
        ans[i] = index;

        if (--priority > 0)
            q.push({{priority, start}, {deadline, index}});
    }

    if (!q.empty()) {
        cout << -1 << '\n';
    } else {
        for (int i = 1; i <= a; ++i)
            cout << ans[i] << (i == a ? '\n' : ' ');
    }

    return 0;
}

